import {
	ChangeDetectionStrategy,
	Component,
	Input,
	effect,
} from '@angular/core';

import { CommonModule } from '@angular/common';
import {
	TranslateModule,
	TranslateService,
} from '@ngx-translate/core';

import { TranslationService } from '../../../core/services/translation.service';

interface TitlePart {
	text: string;
	style?: 'medium' | 'script';
	color?: 'textcolor1' | 'textcolor2';
	break?: boolean | string;
}

interface DescriptionPart {
	text: string;
	bold?: boolean | string;
}

@Component({
	selector: 'app-position',
	standalone: true,
	imports: [
		CommonModule,
		TranslateModule,
	],
	templateUrl: './position.component.html',
	styleUrl: './position.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class PositionComponent {

	@Input() sectionKey = 'THEPOSITION.BRANDING';

	constructor(
		public translationService: TranslationService,
		private translate: TranslateService,
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}

	getTitleParts(): TitlePart[] {
		const parts = this.translate.instant(this.sectionKey + '.TITLE_PARTS');

		return Array.isArray(parts) ? parts : [];
	}

	getDescriptions(): DescriptionPart[] {
		const list = this.translate.instant(this.sectionKey + '.DESCRIPTIONS');

		return Array.isArray(list) ? list : [];
	}
}